#define _GNU_SOURCE
#include <malloc.h>
#include <stdio.h>
#include <unistd.h>

/* Diagnostic only: no allocator interposition, no activity until process exit. */
static void resident(const char *label) {
    FILE *file = fopen("/proc/self/statm", "r");
    unsigned long total = 0, rss = 0;
    if (file && fscanf(file, "%lu %lu", &total, &rss) == 2)
        fprintf(stderr, "ALLOCATOR_EXIT %s rss_bytes=%lu\n", label,
                rss * (unsigned long)sysconf(_SC_PAGESIZE));
    if (file) fclose(file);
}

__attribute__((destructor)) static void report(void) {
    struct mallinfo2 before = mallinfo2();
    resident("before_trim");
    fprintf(stderr, "ALLOCATOR_EXIT arena=%zu allocated=%zu free=%zu mmap=%zu\n",
            before.arena, before.uordblks, before.fordblks, before.hblkhd);
    malloc_info(0, stderr);
    int trimmed = malloc_trim(0);
    resident("after_trim");
    fprintf(stderr, "ALLOCATOR_EXIT trim_result=%d\n", trimmed);
}
